class Solution {
public:
    void wiggleSort(vector<int>& nums) {
        vector<int> s(nums);
        sort(s.begin(), s.end());
        int n = nums.size(), m = (n + 1) / 2;
        int j = n - 1;
        for (int i = m - 1; i >= 0; --i) {
            nums[2 * i] = s[i];
            if (j >= m) nums[2 * i + 1] = s[j--];
        }
    }
};

