class Solution:
    def wiggleSort(self, nums):
        n = len(nums)
        s = sorted(nums)
        median = s[(n - 1) // 2]
        def A(i):
            return (1 + 2 * i) % (n | 1)
        i, j, k = 0, 0, n - 1
        while j <= k:
            if nums[A(j)] > median:
                nums[A(i)], nums[A(j)] = nums[A(j)], nums[A(i)]
                i += 1; j += 1
            elif nums[A(j)] < median:
                nums[A(j)], nums[A(k)] = nums[A(k)], nums[A(j)]
                k -= 1
            else:
                j += 1

