class Solution {
    public void wiggleSort(int[] nums) {
        int n = nums.length;
        int[] s = nums.clone();
        Arrays.sort(s);
        int median = s[(n - 1) / 2];
        int i = 0, j = 0, k = n - 1;
        while (j <= k) {
            int v = nums[vIdx(j, n)];
            if (v > median) { swap(nums, vIdx(i++, n), vIdx(j++, n)); }
            else if (v < median) { swap(nums, vIdx(j, n), vIdx(k--, n)); }
            else j++;
        }
    }
    private int vIdx(int i, int n) { return (1 + 2 * i) % (n | 1); }
    private void swap(int[] a, int x, int y) { int t = a[x]; a[x] = a[y]; a[y] = t; }
}

