var wiggleSort = function(nums) {
    const n = nums.length;
    const s = [...nums].sort((a, b) => a - b);
    const median = s[Math.floor((n - 1) / 2)];
    const A = i => (1 + 2 * i) % (n | 1);
    let i = 0, j = 0, k = n - 1;
    while (j <= k) {
        if (nums[A(j)] > median) {
            [nums[A(i)], nums[A(j)]] = [nums[A(j)], nums[A(i)]];
            i++; j++;
        } else if (nums[A(j)] < median) {
            [nums[A(j)], nums[A(k)]] = [nums[A(k)], nums[A(j)]];
            k--;
        } else j++;
    }
};
